"""Standalone, offline report. Untrusted text enters the DOM only via textContent."""

from __future__ import annotations

import base64
import hashlib
import json
from pathlib import Path
from typing import Any

CSS = """
:root{color-scheme:dark;--bg:#0a101b;--panel:#111b2b;--panel2:#162235;--border:#26364b;--text:#eef3fa;--muted:#9badc4;--mint:#83efd1;--amber:#ffd38a;--blue:#93b8ff;--red:#ffa8b5}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button{font:inherit}a{color:var(--mint)}
.shell{max-width:1440px;margin:auto;padding:30px 40px 45px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border);padding-bottom:22px}.brand{display:flex;align-items:center;gap:12px;font-weight:750;letter-spacing:.14em;font-size:14px}.mark{display:grid;place-items:center;width:36px;height:36px;background:var(--mint);color:var(--bg);border-radius:10px;font-size:20px}.brand span:last-child{color:var(--muted);font-size:11px;letter-spacing:.07em}.pill,.tag{display:inline-flex;align-items:center;gap:7px;border:1px solid var(--border);border-radius:20px;padding:5px 10px;font-size:11px;font-weight:650;letter-spacing:.04em}.pill{color:var(--mint)}.dot{height:6px;width:6px;border-radius:50%;background:currentColor}.eyebrow{font-size:11px;color:var(--mint);text-transform:uppercase;letter-spacing:.18em;font-weight:700}h1{font-size:clamp(30px,3.3vw,48px);line-height:1.12;letter-spacing:-.04em;margin:13px 0 16px;max-width:850px}h2{font-size:19px;margin:0 0 6px;letter-spacing:-.02em}p{margin:0;color:var(--muted)}.hero{display:grid;grid-template-columns:1.4fr .7fr;gap:50px;align-items:center;padding:40px 0 30px}.hero p{max-width:690px;font-size:15px}.boundary{border-left:2px solid var(--mint);padding:14px 18px;background:linear-gradient(90deg,#83efd10c,transparent)}.boundary strong{display:block;font-size:13px;margin-bottom:6px}.boundary p{font-size:12px;line-height:1.7}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:26px}.metric{background:var(--panel);border:1px solid var(--border);padding:20px 22px;border-radius:12px}.metric strong{font-size:30px;letter-spacing:-.04em;line-height:1.2;display:block;margin-bottom:8px}.metric span{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.metric:first-child strong,.metric:last-child strong{color:var(--mint)}
.flow{display:flex;gap:0;border:1px solid var(--border);border-radius:12px;overflow:hidden;margin-bottom:30px}.step{flex:1;padding:14px 20px;background:var(--panel);font-size:12px;border-right:1px solid var(--border)}.step:last-child{border-right:0}.step b{color:var(--blue);margin-right:10px;font-size:10px}.step span{display:block;margin-left:25px;color:var(--muted);font-size:10px;margin-top:2px}.workbench{display:grid;grid-template-columns:minmax(320px,.9fr) minmax(460px,1.25fr);gap:20px;align-items:start}.panel{border:1px solid var(--border);background:var(--panel);border-radius:14px;overflow:hidden}.panel-head{padding:22px 22px 16px}.panel-head p{font-size:12px}.filters{display:flex;gap:6px;padding:0 22px 17px;flex-wrap:wrap}.filter{border:1px solid var(--border);background:transparent;color:var(--muted);border-radius:7px;padding:6px 10px;font-size:11px;cursor:pointer}.filter[aria-pressed=true]{background:#93b8ff18;color:var(--blue);border-color:#526e9e}.scenario{display:flex;align-items:center;justify-content:space-between;width:100%;padding:15px 22px;border:0;border-top:1px solid var(--border);text-align:left;background:transparent;color:var(--text);cursor:pointer;gap:12px}.scenario:hover{background:var(--panel2)}.scenario[aria-current=true]{background:#93b8ff0d;box-shadow:inset 3px 0 var(--blue)}.scenario strong{font-size:12px;display:block;font-weight:600}.scenario small{display:block;font-size:10px;color:var(--muted);margin-top:3px}.tag{font-size:9px;padding:3px 7px;white-space:nowrap}.tag.allow{color:var(--mint);border-color:#83efd13d;background:#83efd10a}.tag.deny{color:var(--amber);border-color:#ffd38a3d;background:#ffd38a0a}.detail-top{padding:22px;border-bottom:1px solid var(--border)}.detail-top .eyebrow{font-size:9px;color:var(--blue);margin-bottom:10px}.detail-top h2{font-size:22px;margin-bottom:10px}.detail-top p{font-size:12px}.decision{margin:18px 22px 0;border:1px solid var(--border);border-radius:9px;padding:13px 15px;display:flex;justify-content:space-between;gap:12px;align-items:center;background:var(--bg)}.decision span{font-size:11px;color:var(--muted)}.decision code{font-size:11px;color:var(--mint);overflow-wrap:anywhere}.decision.denied code{color:var(--amber)}.detail-section{padding:20px 22px 0}.section-label{font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin:0 0 10px;font-weight:650}.binding{font:10px/1.7 ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--blue);overflow-wrap:anywhere;padding:10px 12px;background:var(--bg);border:1px solid var(--border);border-radius:8px}pre{font:11px/1.7 ui-monospace,SFMono-Regular,Menlo,monospace;background:var(--bg);color:#c7d8ef;border:1px solid var(--border);border-radius:8px;padding:15px;margin:0;white-space:pre-wrap;overflow-wrap:anywhere;max-height:410px;overflow:auto}.tabs{display:flex;gap:16px;border-bottom:1px solid var(--border);margin-bottom:14px}.tab{border:0;border-bottom:2px solid transparent;background:none;color:var(--muted);padding:4px 0 10px;font-size:11px;cursor:pointer}.tab[aria-selected=true]{border-bottom-color:var(--mint);color:var(--mint)}.audit-list{padding:0;list-style:none;margin:0}.audit-list li{padding:12px 0;border-bottom:1px solid var(--border);font-size:11px;display:grid;grid-template-columns:32px 1fr;gap:10px}.audit-list li:last-child{border:0}.audit-num{color:var(--muted);font:10px ui-monospace,SFMono-Regular,Menlo,monospace;padding-top:3px}.audit-list strong{font-size:11px;font-weight:550}.audit-list small{display:block;color:var(--muted);font-size:10px;overflow-wrap:anywhere}.detail-bottom{padding-bottom:22px}.note{font-size:11px;color:var(--muted);padding:16px 22px;border-top:1px solid var(--border);background:#0a101b66}.empty{padding:20px;color:var(--muted);font-size:12px}.footer{display:flex;justify-content:space-between;gap:30px;margin-top:28px;border-top:1px solid var(--border);padding-top:18px;font-size:10px;color:var(--muted)}.footer p{max-width:850px}button:focus-visible{outline:2px solid var(--mint);outline-offset:-3px}noscript{display:block;padding:20px;border:1px solid var(--amber);border-radius:10px;margin-bottom:20px;color:var(--amber)}[hidden]{display:none!important}
@media(max-width:980px){.shell{padding:24px}.hero{grid-template-columns:1fr;gap:20px}.workbench{grid-template-columns:1fr}.flow{flex-wrap:wrap}.step{min-width:50%;border-bottom:1px solid var(--border)}.metrics{grid-template-columns:repeat(2,1fr)}.footer{flex-direction:column;gap:10px}}
@media(max-width:540px){.shell{padding:16px}.brand span:last-child{display:none}.hero{padding-top:28px}.metric{padding:15px}.metrics{gap:8px}.step{padding:12px}.panel-head,.detail-top{padding:18px}.scenario{padding:14px 18px}.detail-section{padding:18px 18px 0}.decision{margin:16px 18px 0;align-items:start;flex-direction:column}}
""".strip()

JS = """
"use strict";
const data=JSON.parse(document.getElementById("report-data").textContent);
const $=id=>document.getElementById(id);
let active=data.scenarios[0].id,filter="all",tab="request";
$("count-total").textContent=data.scenarios.length;
$("count-allowed").textContent=data.scenarios.filter(s=>s.actual==="simulated_success").length;
$("count-blocked").textContent=data.scenarios.filter(s=>s.actual!=="simulated_success").length;
$("generated").textContent="Generated "+data.generated_at;
function make(tag,text,className){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(className)el.className=className;return el}
function renderList(){const list=$("scenario-list");list.replaceChildren();const visible=data.scenarios.filter(s=>filter==="all"||(filter==="allowed") === (s.actual==="simulated_success"));for(const s of visible){const b=make("button",undefined,"scenario");b.type="button";b.setAttribute("aria-current",s.id===active?"true":"false");b.setAttribute("aria-controls","decision-detail");const labels=make("span");labels.append(make("strong",s.title),make("small",s.tool+" · "+s.id));b.append(labels,make("span",s.actual==="simulated_success"?"EXECUTED":"BLOCKED","tag "+(s.actual==="simulated_success"?"allow":"deny")));b.addEventListener("click",()=>{active=s.id;renderList();renderDetail()});list.append(b)}}
function renderDetail(){const s=data.scenarios.find(x=>x.id===active);$("detail-title").textContent=s.title;$("detail-description").textContent=s.description;$("decision-code").textContent=s.actual;$("decision-bar").classList.toggle("denied",s.actual!=="simulated_success");$("binding").textContent=s.plan?s.plan.request_digest:"No valid plan: the request fails validation or identity binding.";$("request-json").textContent=typeof s.request==="string"?s.request:JSON.stringify(s.request,null,2);$("result-json").textContent=JSON.stringify(s.result,null,2);$("plan-json").textContent=s.plan?JSON.stringify(s.plan,null,2):"Validation or identity binding rejected this request before a plan could be produced.";$("expected").textContent="Expected outcome verified: "+s.expected+". No external action occurred.";const list=$("audit-list");list.replaceChildren();for(const e of s.audit){const li=make("li");li.append(make("span",String(e.event_id).padStart(2,"0"),"audit-num"));const info=make("div");info.append(make("strong",e.event.replaceAll("_"," ")+" · "+e.code),make("small",e.tenant_id+" / "+e.principal_id));list.append(li);li.append(info)}if(!s.audit.length)list.append(make("li","Dry-run planning does not persist audit events."));renderTab()}
function renderTab(){for(const name of ["request","plan","result"]){$(name+"-json").hidden=name!==tab;$("tab-"+name).setAttribute("aria-selected",name===tab?"true":"false")}}
for(const button of document.querySelectorAll(".filter"))button.addEventListener("click",()=>{filter=button.dataset.filter;for(const b of document.querySelectorAll(".filter"))b.setAttribute("aria-pressed",b===button?"true":"false");const visible=data.scenarios.filter(s=>filter==="all"||(filter==="allowed")===(s.actual==="simulated_success"));if(!visible.some(s=>s.id===active)&&visible.length)active=visible[0].id;renderList();renderDetail()});
for(const name of ["request","plan","result"])$("tab-"+name).addEventListener("click",()=>{tab=name;renderTab()});
renderList();renderDetail();
""".strip()


def _hash(source: str) -> str:
    return base64.b64encode(hashlib.sha256(source.encode("utf-8")).digest()).decode("ascii")


def render_report(data: dict[str, Any]) -> str:
    embedded = (json.dumps(data, ensure_ascii=True, separators=(",", ":"))
                .replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026"))
    csp = ("default-src 'none'; base-uri 'none'; form-action 'none'; "
           f"style-src 'sha256-{_hash(CSS)}'; script-src 'sha256-{_hash(JS)}'; "
           "connect-src 'none'; img-src 'none'; object-src 'none'")
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="{csp}">
<meta name="description" content="Offline synthetic tool approval decisions, exact-action binding, and transactional audit evidence.">
<title>Bound — Tool approval gateway</title><style>{CSS}</style></head>
<body><main class="shell"><header><div class="brand"><span class="mark" aria-hidden="true">↳</span>BOUND <span>TOOL APPROVAL GATEWAY</span></div><span class="pill"><span class="dot"></span>OFFLINE SIMULATION</span></header>
<section class="hero"><div><div class="eyebrow">Reference control plane / Synthetic evidence</div><h1>Every action needs<br>a decision.</h1><p>A small, inspectable boundary between an agent's intent and a tool's effect. Review the exact request, inspect its approval binding, and follow the local audit trail.</p></div><aside class="boundary"><strong>Approval is tied to the exact action.</strong><p>Identity · tool · target · arguments · policy · expiry<br>Change the request and the grant stops matching. Reuse a consumed grant and execution stops.</p></aside></section>
<section class="metrics" aria-label="Synthetic demo outcomes"><div class="metric"><strong id="count-total">—</strong><span>Verified scenarios</span></div><div class="metric"><strong id="count-allowed">—</strong><span>Simulated executions</span></div><div class="metric"><strong id="count-blocked">—</strong><span>Expected refusals</span></div><div class="metric"><strong>0</strong><span>External actions</span></div></section>
<section class="flow" aria-label="Control flow"><div class="step"><b>01</b>Validate<span>Strict JSON &amp; trusted identity</span></div><div class="step"><b>02</b>Decide<span>Fixed policy &amp; target allowlist</span></div><div class="step"><b>03</b>Approve<span>Separate authority &amp; signed grant</span></div><div class="step"><b>04</b>Commit<span>Local effect, grant &amp; audit</span></div></section>
<noscript>This interactive report requires JavaScript. All evidence is also available in the companion JSON file. No network access is used.</noscript>
<div class="workbench"><section class="panel"><div class="panel-head"><h2>Decision explorer</h2><p>Select a scenario to inspect its control path.</p></div><div class="filters" aria-label="Filter scenarios"><button class="filter" data-filter="all" aria-pressed="true">All decisions</button><button class="filter" data-filter="allowed" aria-pressed="false">Executed</button><button class="filter" data-filter="blocked" aria-pressed="false">Blocked</button></div><div id="scenario-list"></div></section>
<section class="panel" id="decision-detail" aria-label="Selected scenario"><div class="detail-top"><div class="eyebrow">Exact request / observable outcome</div><h2 id="detail-title"></h2><p id="detail-description"></p></div><div class="decision" id="decision-bar"><span>Gateway outcome</span><code id="decision-code"></code></div><div class="detail-section"><h3 class="section-label">Canonical request / SHA-256</h3><div class="binding" id="binding"></div></div><div class="detail-section"><div class="tabs" role="tablist" aria-label="Inspect scenario"><button class="tab" id="tab-request" role="tab" aria-selected="true" aria-controls="request-json">Request</button><button class="tab" id="tab-plan" role="tab" aria-selected="false" aria-controls="plan-json">Dry-run plan</button><button class="tab" id="tab-result" role="tab" aria-selected="false" aria-controls="result-json">Result</button></div><pre id="request-json" role="tabpanel" aria-labelledby="tab-request"></pre><pre id="plan-json" role="tabpanel" aria-labelledby="tab-plan" hidden></pre><pre id="result-json" role="tabpanel" aria-labelledby="tab-result" hidden></pre></div><div class="detail-section detail-bottom"><h3 class="section-label">Persisted audit events</h3><ol class="audit-list" id="audit-list"></ol></div><div class="note" id="expected"></div></section></div>
<footer class="footer"><p>Original reference implementation. Synthetic identities and fixtures only. These outcomes demonstrate this local simulator; they do not establish production security, prompt-injection resistance, or exactly-once effects in external systems.</p><span id="generated"></span></footer></main>
<script id="report-data" type="application/json">{embedded}</script><script>{JS}</script></body></html>
"""


def write_report(data: dict[str, Any], directory: Path) -> tuple[Path, Path]:
    directory.mkdir(parents=True, exist_ok=True)
    json_path, html_path = directory / "report.json", directory / "report.html"
    json_path.write_text(json.dumps(data, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")
    html_path.write_text(render_report(data), encoding="utf-8")
    return html_path, json_path
